    var payload:[String:Any]{["id":id,"instance":instance,"version":version,"loader":loader,"world":world,"started":started.timeIntervalSince1970,"seconds":Int(seconds),"friends":friends]}
    static func remote(_ object:[String:Any])->PlaySession?{guard let id=object["id"] as? String,let name=object["instance"] as? String,let start=object["started"] as? Double else{return nil};return PlaySession(id:id,instance:name,version:object["version"] as? String ?? "",loader:object["loader"] as? String ?? "",world:object["world"] as? String ?? "",started:Date(timeIntervalSince1970:start),seconds:object["seconds"] as? Double ?? 0,friends:object["friends"] as? [String] ?? [],active:false,runDirectory:"")}
}
