    func note(_ value:String,for id:String){notes[id]=String(value.prefix(80));flush()}
    func begin(_ game:GameInstance,name:String,id:String){guard active[game.id]==nil else{return};let record=PlaySession(id:id,instance:name,version:game.version,loader:game.loader,world:"",started:Date(),seconds:0,friends:launchFriends.filter{id in friends.contains{$0.id==id}},active:true,runDirectory:game.runDirectory);launchFriends=[];sessions.insert(record,at:0);active[game.id]=record.id;flush();if heartbeat==nil{heartbeat=Task{while !Task.isCancelled{try? await Task.sleep(for:.seconds(60));guard !Task.isCancelled else{return};self.tick();try? await self.sync()}}}}
    func finish(_ id:String){guard let record=active.removeValue(forKey:id),let index=sessions.firstIndex(where:{$0.id==record}) else{return};sessions[index].seconds=max(sessions[index].seconds,Date().timeIntervalSince(sessions[index].started));sessions[index].active=false;let session=sessions[index];flush();Task{let world=await Task.detached(priority:.utility){Self.recentWorld(session)}.value;if let index=self.sessions.firstIndex(where:{$0.id==record}){self.sessions[index].world=world;self.flush()};try? await self.sync()};if active.isEmpty{heartbeat?.cancel();heartbeat=nil}}
    private nonisolated static func recentWorld(_ session:PlaySession)->String{let root=URL(fileURLWithPath:session.runDirectory).appendingPathComponent("saves");let dirs=(try? FileManager.default.contentsOfDirectory(at:root,includingPropertiesForKeys:nil)) ?? [];let candidates=dirs.compactMap{dir->(String,Date)? in guard let date=try? dir.appendingPathComponent("level.dat").resourceValues(forKeys:[.contentModificationDateKey]).contentModificationDate,date>=session.started.addingTimeInterval(-2) else{return nil};return(dir.lastPathComponent,date)}.sorted{$0.1>$1.1};return candidates.first?.0 ?? ""}
    func refreshLocal(){let folder=directory.appendingPathComponent("receipts");var completed:[URL]=[];for index in sessions.indices{let path=folder.appendingPathComponent(sessions[index].id.uppercased()+".json");let receipt=NativeScanner.readJSON(path);guard receipt["id"] as? String==sessions[index].id.uppercased(),let seconds=receipt["seconds"] as? Double,seconds.isFinite,seconds>=0 else{continue};sessions[index].seconds=max(sessions[index].seconds,seconds);if let world=receipt["world"] as? String,!world.isEmpty{sessions[index].world=world};let finished=receipt["finished"] as? Bool ?? false;let modified=(try? path.resourceValues(forKeys:[.contentModificationDateKey]).contentModificationDate) ?? .distantPast;let pid=receipt["pid"] as? Int32 ?? 0;sessions[index].active = !finished && Date().timeIntervalSince(modified)<95 && pid>0 && Darwin.kill(pid,0)==0;if finished{completed.append(path)}};if flush(){for path in completed{try? FileManager.default.removeItem(at:path)}}}
