    private func reload()async throws{guard let result=try await call("friends") as? [String:Any] else{throw FileTransactions.error("同步服务返回异常。")};func profile(_ value:Any?)throws->HarborFriend{let result=try JSONDecoder().decode(HarborFriend.self,from:JSONSerialization.data(withJSONObject:value ?? [:]));guard UUID(uuidString:result.id) != nil,result.name.count<=64,result.code.count<=32,result.skinHash.isEmpty || result.skinHash.range(of:"^[a-f0-9]{64}$",options:.regularExpression) != nil,["default","slim"].contains(result.skinModel) else{throw FileTransactions.error("好友资料格式无效。")};return result};me=try profile(result["me"]);friends=try (result["friends"] as? [Any] ?? []).map{try profile($0)};requests=try (result["requests"] as? [Any] ?? []).map{try profile($0)};sent=try (result["sent"] as? [Any] ?? []).map{try profile($0)};let allowed=Set(friends.map(\.id));remoteSessions=remoteSessions.filter{allowed.contains($0.key)};for friend in friends where !friend.sharing{remoteSessions[friend.id]=nil};skinPaths=skinPaths.filter{key,_ in allowed.contains(key) && friends.contains(where:{$0.id==key && !$0.skinHash.isEmpty})};chat.reconcile(allowed);chat.connect();status="好友列表已同步"}
