                if let friend{NativeFriendConversation(model:model,chat:social.chat,friend:friend).id(friend.id)}
                HStack{Text(selected.isEmpty ? "本机游玩记录":"好友最近游戏").font(.system(size:19,weight:.semibold));Spacer();Picker("筛选",selection:$filter){Text("全部").tag("all");Text("与好友游玩").tag("friends");if !selected.isEmpty,let me=social.me{Text("与我游玩").tag("friend:"+me.id)};ForEach(social.friends){friend in Text(social.notes[friend.id].flatMap{$0.isEmpty ? nil:$0} ?? friend.name).tag("friend:"+friend.id)}}.frame(width:200)}
                if shown.isEmpty{ContentUnavailableView("暂无游玩记录",systemImage:"clock",description:Text("从 MC Harbor 启动后记录实例和时长；联机时在下方选择同行好友。"))}else{ForEach(shown){session in VStack(alignment:.leading,spacing:7){HStack{Text(session.instance).font(.system(size:16,weight:.medium));Spacer();Text(session.active ? "游玩中":duration(session.seconds)).font(.system(size:12)).foregroundStyle(.secondary)};Text(session.summary).font(.system(size:11)).foregroundStyle(.secondary);HStack{Text(session.started,format:.dateTime.year().month().day().hour().minute());if !session.friends.isEmpty{Text("同行："+companionNames(session))}}.font(.system(size:10)).foregroundStyle(.secondary)}.padding(17).frame(maxWidth:.infinity,alignment:.leading).background(Color.primary.opacity(0.035),in:RoundedRectangle(cornerRadius:17))}}
                if selected.isEmpty,!social.friends.isEmpty{DisclosureGroup("下次启动的同行好友"){ForEach(social.friends){friend in Toggle(friend.name,isOn:Binding(get:{social.launchFriends.contains(friend.id)},set:{enabled in if enabled{social.launchFriends.append(friend.id)}else{social.launchFriends.removeAll{$0==friend.id}}}))};Text("仅记录你选择的同行信息，不会自动判定对方是否进入同一服务器。").font(.system(size:10)).foregroundStyle(.secondary)}}
            }.frame(maxWidth:.infinity,alignment:.leading)
        };Text(social.status).font(.system(size:11)).foregroundStyle(.secondary).textSelection(.enabled)
    }.padding(28)}.onAppear{social.refreshLocal();endpoint=social.endpoint;name=model.preferences.username;if let account=model.selectedAccount{model.loadSkin(account)};if !social.endpoint.isEmpty{social.refresh()}}.alert("移除好友？",isPresented:$removing){Button("取消",role:.cancel){};Button("移除",role:.destructive){if let friend{social.remove(friend);selected=""}}}message:{Text("双方将无法继续查看彼此共享的游戏记录与皮肤。")}}
    private func friendRow(_ name:String,symbol:String,selected:Bool,skin:String?=nil,subtitle:String?=nil)->some View{HStack(spacing:10){if let skin,let image=MinecraftHeads.image(skin){Image(nsImage:image).resizable().interpolation(.none).scaledToFit().frame(width:29,height:29).clipShape(RoundedRectangle(cornerRadius:6)).accessibilityLabel(name+" 的 Minecraft 皮肤头像")}else{Image(systemName:symbol).frame(width:29)};VStack(alignment:.leading,spacing:4){Text(name).lineLimit(1);if let subtitle{Text(subtitle).font(.system(size:10)).foregroundStyle(.secondary).lineLimit(1)}}.padding(.trailing,6)}.font(.system(size:13,weight:.medium)).padding(14).frame(maxWidth:.infinity,alignment:.leading).background(model.themeColor.opacity(selected ? 0.15:0.025),in:RoundedRectangle(cornerRadius:15)).contentShape(RoundedRectangle(cornerRadius:15))}
    private func companionNames(_ session:PlaySession)->String{session.friends.map{ id -> String in if id==social.me?.id{return "我"};if let note=social.notes[id],!note.isEmpty{return note};return social.friends.first(where:{$0.id==id})?.name ?? "好友"}.joined(separator:"、")}
    private func duration(_ value:Double)->String{let minutes=Int(value/60);return minutes>=60 ? "\(minutes/60) 小时 \(minutes%60) 分钟":"\(minutes) 分钟"}
}
